	AND platform_type != 'admin'

		AND menu_name like concat('%', #{menuName}, '%')


		AND visible = #{visible}


		AND status = #{status}


order by platform_type,parent_id, order_num

		select distinct m.menu_id, m.parent_id, m.menu_name, m.path, m.component, m.`query`, m.route_name, m.visible, m.status, ifnull(m.perms,'') as perms, m.is_frame,
		                m.is_cache, m.menu_type, m.icon, m.order_num, m.create_time,m.platform_type,m.rich_text
		from sys_menu m
		left join sys_role_menu rm on m.menu_id = rm.menu_id
		left join sys_user_role ur on rm.role_id = ur.role_id
		left join sys_role ro on ur.role_id = ro.role_id
		where ur.user_id = #{params.userId}

            AND m.menu_name like concat('%', #{menuName}, '%')


            AND m.visible = #{visible}


            AND m.status = #{status}


            AND m.platform_type = #{platformType}

		order by m.parent_id, m.order_num

select m.menu_id 'menuId',rm.data_scope 'dataScope' from sys_menu m left join sys_role_menu rm on m.menu_id = rm.menu_id where rm.role_id = #{roleId}
and m.menu_id not in (select m.parent_id from sys_menu m inner join sys_role_menu rm on m.menu_id = rm.menu_id and rm.role_id = #{roleId})
order by m.parent_id, m.order_num

